def _latest_intent(
    intents: dict[str, dict[str, dict[str, Any]]],
    job_id: str,
) -> dict[str, Any] | None:
    job_intents = intents.get(job_id)
    if not job_intents:
        return None
    # The current reservation is the latest one committed for the job.
    key = max(job_intents, key=lambda reserve_key:
              (job_intents[reserve_key]["at"], reserve_key))
    return job_intents[key]


def _latest_plan(
    plans: dict[str, dict[str, dict[str, Any]]],
    job_id: str,
) -> tuple[str, dict[str, Any]] | None:
    job_plans = plans.get(job_id)
    if not job_plans:
        return None
    return _ordered_plans(job_plans)[-1]


